/* ── Exercise Layout ─────────────────────────────────────
 *  4-row grid layout for exercise views (game-master, player).
 *  Row 1: Header (exercise title, clocks, phase)
 *  Row 2: Overview (timeline + issue list)
 *  Row 3: Details (collapsible)
 *  Row 4: Controls (action bar)
 * ──────────────────────────────────────────────────────── */

@layer components {
  .exercise-layout {
    display: grid;
    grid-template-rows: auto 1fr auto auto;
    height: 100dvh;
    overflow: hidden;
  }

  .exercise-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-md);
    padding: var(--spacing-sm) var(--spacing-lg);
    border-bottom: 1px solid var(--color-muted);
    background: var(--color-card);
  }

  .exercise-header__title {
    font-size: var(--font-size-lg);
    font-weight: 600;
    color: var(--color-foreground);
  }

  .exercise-header__clocks {
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
  }

  .exercise-clock {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--spacing-2xs);
  }

  .exercise-clock__label {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  .exercise-clock__value {
    font-family: var(--font-mono);
    font-size: var(--font-size-xl);
    font-weight: 600;
    color: var(--color-foreground);
  }

  .exercise-overview {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
    overflow: auto;
  }

  .exercise-overview--wide {
    grid-template-columns: 2fr 1fr;
  }

  .exercise-details {
    padding: var(--spacing-sm) var(--spacing-lg);
    border-top: 1px solid var(--color-muted);
    background: var(--color-card);
    overflow: auto;
    max-height: 30vh;
  }

  .exercise-details[hidden] {
    display: none;
  }

  .exercise-controls {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-sm) var(--spacing-lg);
    border-top: 1px solid var(--color-muted);
    background: var(--color-card);
  }

  .exercise-controls__group {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
  }

  .exercise-controls__spacer {
    flex: 1;
  }

  /* Speed factor slider */
  .exercise-speed {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
  }

  .exercise-speed__label {
    font-size: var(--font-size-sm);
    color: var(--color-muted-foreground);
  }

  .exercise-speed__value {
    font-family: var(--font-mono);
    font-size: var(--font-size-sm);
    font-weight: 600;
    min-width: 3ch;
    text-align: center;
  }

  /* Phase badge */
  .exercise-phase {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-2xs);
    padding: var(--spacing-2xs) var(--spacing-sm);
    border-radius: var(--radius-sm);
    font-size: var(--font-size-xs);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  .exercise-phase[data-phase="setup"] {
    background: var(--color-info);
    color: var(--color-info-foreground);
  }

  .exercise-phase[data-phase="briefing"] {
    background: var(--color-primary);
    color: var(--color-primary-foreground);
  }

  .exercise-phase[data-phase="running"] {
    background: var(--color-success);
    color: var(--color-success-foreground);
  }

  .exercise-phase[data-phase="paused"] {
    background: var(--color-warning);
    color: var(--color-warning-foreground);
  }

  .exercise-phase[data-phase="completed"] {
    background: var(--color-muted);
    color: var(--color-muted-foreground);
  }

  /* ── Briefing Overlay ──────────────────────────────────── */

  .briefing-overlay__backdrop {
    position: fixed;
    inset: 0;
    z-index: var(--z-modal);
    background: oklch(8% 0.008 250 / 85%);
  }

  .briefing-overlay__panel {
    position: fixed;
    inset: 0;
    z-index: var(--z-modal);
    display: flex;
    flex-direction: column;
    max-width: 48rem;
    max-height: 90dvh;
    margin: auto;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    background: var(--color-card);
    overflow: hidden;
  }

  .briefing-overlay__header {
    padding: var(--spacing-lg) var(--spacing-xl);
    border-bottom: 1px solid var(--color-border);
  }

  .briefing-overlay__title {
    font-size: var(--font-size-xl);
    font-weight: 700;
    color: var(--color-foreground);
    margin: 0;
  }

  .briefing-overlay__body {
    flex: 1;
    overflow: auto;
    padding: var(--spacing-lg) var(--spacing-xl);
  }

  .briefing-overlay__section {
    margin-bottom: var(--spacing-lg);
  }

  .briefing-overlay__section:last-child {
    margin-bottom: 0;
  }

  .briefing-overlay__heading {
    font-size: var(--font-size-sm);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-primary);
    margin: 0 0 var(--spacing-sm);
  }

  .briefing-overlay__text {
    font-size: var(--font-size-base);
    color: var(--color-foreground);
    line-height: 1.7;
  }

  .briefing-overlay__list {
    font-size: var(--font-size-sm);
    color: var(--color-foreground);
    padding-left: var(--spacing-lg);
    line-height: 1.8;
  }

  .briefing-overlay__roles {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-sm);
  }

  .briefing-overlay__role {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xs) var(--spacing-sm);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    font-size: var(--font-size-sm);
    color: var(--color-foreground);
  }

  .briefing-overlay__role-type {
    font-size: var(--font-size-xs);
    color: var(--color-muted-foreground);
  }

  .briefing-overlay__footer {
    display: flex;
    justify-content: center;
    padding: var(--spacing-lg) var(--spacing-xl);
    border-top: 1px solid var(--color-border);
  }
}

