  switch (msg.type) {
    case "exercise_stopped":
      // Don't navigate away if completed — let the completion overlay handle it
      if (store.phase() !== "completed") {
        onStopped?.();
      }
      break;
    case "snapshot":
      store.applySnapshot(msg);
      break;
    case "state_changes":
      for (const change of msg.changes) {
        handleStateChange(change, store);
      }
      break;
  }
}

