+        >
+          Return to Home
+        </button>
+      </footer>
+    </div>
+  `,
+})
+export class CompletionOverlayComponent {
+  readonly tier = input<string | null>(null);
+  readonly closed = output();
+
+  protected get config(): { heading: string; message: string } {
+    const t = this.tier();
